fn get_file_to_check(
    filename: &str,
    ignore_missing: bool,
    res: &mut ChecksumResult,
) -> Option<Box<dyn Read>> {
    if filename == "-" {
        Some(Box::new(stdin())) // Use stdin if "-" is specified in the checksum file
