struct Options {
    algo_name: &'static str,
    digest: Box<dyn Digest + 'static>,
    output_bits: usize,
    tag: bool, // will cover the --untagged option
    length: Option<usize>,
    output_format: OutputFormat,
    asterisk: bool, // if we display an asterisk or not (--binary/--text)
}

/// Convert an `OsStr` to the bytes that should be written to stdout.
///
/// On Unix, filenames are arbitrary byte sequences and must be printed
/// verbatim. On other platforms, fall back to a lossy conversion.
fn os_str_bytes(s: &OsStr) -> Vec<u8> {
    #[cfg(unix)]
    {
        use std::os::unix::ffi::OsStrExt;
        s.as_bytes().to_vec()
    }
    #[cfg(not(unix))]
    {
        s.to_string_lossy().into_owned().into_bytes()
    }
}

/// Print a line built from a `prefix`, the raw filename bytes, and a `suffix`.
fn print_filename_line(prefix: &str, filename: &Path, suffix: &str) -> io::Result<()> {
    let stdout = stdout();
    let mut stdout = stdout.lock();
    stdout.write_all(prefix.as_bytes())?;
    stdout.write_all(&os_str_bytes(filename.as_os_str()))?;
    stdout.write_all(suffix.as_bytes())?;
    stdout.write_all(b"\n")
}

