// The BSD checksum output is 5 digit integer
let bsd_width = 5;
match (options.algo_name, not_file) {
    (ALGORITHM_OPTIONS_SYSV, true) => println!(
        "{} {}",
        sum.parse::<u16>().unwrap(),
        div_ceil(sz, options.output_bits)
    ),
    (ALGORITHM_OPTIONS_SYSV, false) => {
        let prefix = format!(
            "{} {} ",
            sum.parse::<u16>().unwrap(),
            div_ceil(sz, options.output_bits)
        );
        print_filename_line(&prefix, filename, "")?;
    }
    (ALGORITHM_OPTIONS_BSD, true) => println!(
        "{:0bsd_width$} {:bsd_width$}",
        sum.parse::<u16>().unwrap(),
        div_ceil(sz, options.output_bits)
    ),
    (ALGORITHM_OPTIONS_BSD, false) => {
        let prefix = format!(
            "{:0bsd_width$} {:bsd_width$} ",
            sum.parse::<u16>().unwrap(),
            div_ceil(sz, options.output_bits)
        );
        print_filename_line(&prefix, filename, "")?;
    }
    (ALGORITHM_OPTIONS_CRC, true) => println!("{sum} {sz}"),
    (ALGORITHM_OPTIONS_CRC, false) => {
        let prefix = format!("{sum} {sz} ");
        print_filename_line(&prefix, filename, "")?;
    }
    (ALGORITHM_OPTIONS_BLAKE2B, _) if options.tag => {
        if let Some(length) = options.length {
            // Multiply by 8 here, as we want to print the length in bits.
            let prefix = format!("BLAKE2b-{} (", length * 8);
            let suffix = format!(") = {sum}");
            print_filename_line(&prefix, filename, &suffix)?;
        } else {
            let suffix = format!(") = {sum}");
            print_filename_line("BLAKE2b (", filename, &suffix)?;
        }
    }
    _ => {
        if options.tag {
            let prefix = format!("{} (", options.algo_name.to_ascii_uppercase());
            let suffix = format!(") = {sum}");
            print_filename_line(&prefix, filename, &suffix)?;
        } else {
            let prefix = if options.asterisk { "*" } else { " " };
            let prefix = format!("{sum} {prefix}");
            print_filename_line(&prefix, filename, "")?;
        }
    }
}

